// ListConversationsParams defines parameters for ListConversations.
type ListConversationsParams struct {
	InboxId *uuid.UUID `form:"inbox_id,omitempty" json:"inbox_id,omitempty"`

	// ContactId Only this contact's conversations. A contact of another workspace answers `404`.
	ContactId *uuid.UUID `form:"contact_id,omitempty" json:"contact_id,omitempty"`

	// Status Only conversations in these statuses, e.g. `status=open,pending` for what is still to
	// do. Repeat the parameter or give a comma-separated list. Without it every status is
	// listed, snoozed included.
	Status *[]ConversationStatus `form:"status,omitempty" json:"status,omitempty"`

	// Assignee A member id, `me` (member sessions only) or `unassigned`.
	Assignee *string    `form:"assignee,omitempty" json:"assignee,omitempty"`
	LabelId  *uuid.UUID `form:"label_id,omitempty" json:"label_id,omitempty"`

	// Spam `true` lists only conversations flagged as spam (the spam view); without it, or with
	// `false`, spam is left out.
	Spam *bool `form:"spam,omitempty" json:"spam,omitempty"`

	// Kind Only conversations of these kinds, e.g. `feedback` for the feedback view. Repeat the
	// parameter (`kind=feedback&kind=conversation`) or give a comma-separated list
	// (`kind=feedback,conversation`).
	Kind *ConversationKinds `form:"kind,omitempty" json:"kind,omitempty"`

	// ChannelKind Only conversations that started on a channel of these kinds (`channel_kind` on the
	// conversation). Repeat the parameter or give a comma-separated list. Conversations
	// without a `channel_kind` never match.
	ChannelKind *[]ChannelKind `form:"channel_kind,omitempty" json:"channel_kind,omitempty"`

	// Site Only conversations sent from a page of this site: an origin, `scheme://host[:port]`,
	// matched against the origin of `page.page_url`.
	Site *string `form:"site,omitempty" json:"site,omitempty"`

	// Category Only feedback of this category key (implies `kind=feedback`; with a `kind` list that lacks
	// `feedback`, `400`). Any key of the pattern is accepted: a key no inbox lists matches nothing.
	Category *FeedbackCategory `form:"category,omitempty" json:"category,omitempty"`

	// Page Only conversations sent from this documentation page (a URL; query and fragment are
	// ignored).
	Page *string `form:"page,omitempty" json:"page,omitempty"`

	// BroadcastId Only conversations opened by replies to this broadcast.
	BroadcastId *uuid.UUID `form:"broadcast_id,omitempty" json:"broadcast_id,omitempty"`

	// IdeaId Only the feedback linked to this roadmap idea. An idea of an inbox the caller cannot
	// see answers `404`.
	IdeaId *uuid.UUID `form:"idea_id,omitempty" json:"idea_id,omitempty"`

	// Idea `none` lists only feedback that is not linked to an idea (and no other kind).
	Idea *ListConversationsParamsIdea `form:"idea,omitempty" json:"idea,omitempty"`

	// Pinned `true` lists only the conversations the calling member pinned, `false` only the others;
	// without it, both. Member sessions only (`400 validation_failed` for API keys).
	Pinned *bool `form:"pinned,omitempty" json:"pinned,omitempty"`

	// Q Full-text search (Postgres `simple` configuration, `websearch` syntax).
	Q *Search `form:"q,omitempty" json:"q,omitempty"`

	// Cursor The `next_cursor` of the previous page.
	Cursor *Cursor `form:"cursor,omitempty" json:"cursor,omitempty"`

	// Limit Page size, 1 to 100; 25 by default.
	Limit *Limit `form:"limit,omitempty" json:"limit,omitempty"`

	// YuvaWorkspace The workspace to act on; see "Workspace selection".
	YuvaWorkspace *WorkspaceHeader `json:"Yuva-Workspace,omitempty"`
}

